using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Media;
using System.Windows.Automation;

namespace FrostTodo {
 public static class Ui {
  public const double InputHeight=36;
  public static FontFamily CurrentFont=FontCatalog.SystemFont;
  public static string FontName{get{return CurrentFont.Source;}}
  public static void SetFont(string key){FontFamily next=FontCatalog.Resolve(key);if(Object.ReferenceEquals(next,CurrentFont))return;CurrentFont=next;if(Application.Current!=null)Application.Current.Resources["UiFont"]=CurrentFont;}
  public static SolidColorBrush Brush(string hex){return new SolidColorBrush((Color)ColorConverter.ConvertFromString(hex));}
  public static void PaintWindowSurface(Border border,Color tint,int opacity,bool nativeTint=false){byte alpha=(byte)Math.Round(Math.Max(0,Math.Min(100,opacity))*2.55);border.CornerRadius=new CornerRadius(0);border.BorderThickness=new Thickness(1);border.BorderBrush=new SolidColorBrush(Color.FromArgb(alpha,255,255,255));border.Background=nativeTint?new SolidColorBrush(Color.FromArgb(1,255,255,255)):new SolidColorBrush(Color.FromArgb(alpha,tint.R,tint.G,tint.B));}
  public static void Install(Application app){
   app.Resources["UiFont"]=CurrentFont;TextAppearance.Publish(new Preferences());
   app.Resources["Ink"]=Brush("#263344");app.Resources["Muted"]=Brush("#66778B");app.Resources["Accent"]=Brush("#52749B");app.Resources["Field"]=Brush("#55FFFFFF");app.Resources["Line"]=Brush("#178A9AAE");app.Resources["Hover"]=Brush("#19778BA4");app.Resources["Selected"]=Brush("#556C8DAC");
   string xaml=@"<ResourceDictionary xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml'>
   <Style TargetType='TextBlock'><Setter Property='Foreground' Value='{DynamicResource Ink}'/><Setter Property='FontFamily' Value='Segoe UI Variable Text,Microsoft YaHei UI'/><Setter Property='FontSize' Value='14'/></Style>
   <Style TargetType='Control'><Setter Property='FontFamily' Value='Segoe UI Variable Text,Microsoft YaHei UI'/><Setter Property='FontSize' Value='13'/><Setter Property='Foreground' Value='{DynamicResource Ink}'/></Style>
   <Style TargetType='Button'><Setter Property='Foreground' Value='{DynamicResource Ink}'/><Setter Property='FontFamily' Value='Segoe UI Variable Text,Microsoft YaHei UI'/><Setter Property='FontSize' Value='12'/><Setter Property='Padding' Value='9,6'/><Setter Property='Background' Value='Transparent'/><Setter Property='BorderBrush' Value='Transparent'/><Setter Property='BorderThickness' Value='0'/><Setter Property='HorizontalContentAlignment' Value='Center'/><Setter Property='VerticalContentAlignment' Value='Center'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='Button'><Border x:Name='chrome' Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='{TemplateBinding BorderThickness}' CornerRadius='9' Padding='{TemplateBinding Padding}'><ContentPresenter HorizontalAlignment='{TemplateBinding HorizontalContentAlignment}' VerticalAlignment='{TemplateBinding VerticalContentAlignment}'/></Border><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='chrome' Property='Background' Value='{DynamicResource Hover}'/></Trigger><Trigger Property='IsPressed' Value='True'><Setter TargetName='chrome' Property='Opacity' Value='.65'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='.4'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
   <Style TargetType='TextBox'><Setter Property='Foreground' Value='{DynamicResource Ink}'/><Setter Property='Background' Value='{DynamicResource Field}'/><Setter Property='BorderBrush' Value='{DynamicResource Line}'/><Setter Property='BorderThickness' Value='1'/><Setter Property='Padding' Value='10,7'/><Setter Property='FontFamily' Value='Segoe UI Variable Text,Microsoft YaHei UI'/><Setter Property='FontSize' Value='13'/><Setter Property='MinHeight' Value='34'/><Setter Property='VerticalContentAlignment' Value='Center'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='TextBox'><Border x:Name='edge' Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='1' CornerRadius='9'><ScrollViewer x:Name='PART_ContentHost' Margin='{TemplateBinding Padding}'/></Border><ControlTemplate.Triggers><Trigger Property='IsKeyboardFocusWithin' Value='True'><Setter TargetName='edge' Property='BorderBrush' Value='{DynamicResource Accent}'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
   <Style TargetType='ComboBox'><Setter Property='Foreground' Value='{DynamicResource Ink}'/><Setter Property='FontFamily' Value='Segoe UI Variable Text,Microsoft YaHei UI'/><Setter Property='FontSize' Value='12'/><Setter Property='MinHeight' Value='34'/><Setter Property='Padding' Value='10,7'/><Setter Property='Background' Value='{DynamicResource Field}'/><Setter Property='BorderBrush' Value='{DynamicResource Line}'/><Setter Property='ScrollViewer.HorizontalScrollBarVisibility' Value='Disabled'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='ComboBox'><Grid><ToggleButton Focusable='False' IsChecked='{Binding IsDropDownOpen,Mode=TwoWay,RelativeSource={RelativeSource TemplatedParent}}'><ToggleButton.Template><ControlTemplate TargetType='ToggleButton'><Border Background='{DynamicResource Field}' BorderBrush='{DynamicResource Line}' BorderThickness='1' CornerRadius='9'><TextBlock Text='⌄' FontSize='12' HorizontalAlignment='Right' VerticalAlignment='Center' Margin='0,0,10,3'/></Border></ControlTemplate></ToggleButton.Template></ToggleButton><ContentPresenter Margin='10,5,27,5' Content='{TemplateBinding SelectionBoxItem}' ContentTemplate='{TemplateBinding SelectionBoxItemTemplate}' VerticalAlignment='Center' IsHitTestVisible='False'/><Popup Name='PART_Popup' Placement='Bottom' IsOpen='{TemplateBinding IsDropDownOpen}' AllowsTransparency='True' Focusable='False' PopupAnimation='Fade'><Border Background='#F3F6FA' BorderBrush='#CCD4DF' BorderThickness='1' CornerRadius='10' Padding='4' MinWidth='{Binding ActualWidth,RelativeSource={RelativeSource TemplatedParent}}'><ScrollViewer MaxHeight='240' CanContentScroll='True'><StackPanel IsItemsHost='True'/></ScrollViewer></Border></Popup></Grid></ControlTemplate></Setter.Value></Setter></Style>
   <Style TargetType='ComboBoxItem'><Setter Property='Foreground' Value='#263344'/><Setter Property='Padding' Value='9,6'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='ComboBoxItem'><Border x:Name='b' CornerRadius='6' Background='Transparent' Padding='{TemplateBinding Padding}'><ContentPresenter/></Border><ControlTemplate.Triggers><Trigger Property='IsHighlighted' Value='True'><Setter TargetName='b' Property='Background' Value='#DEE7F1'/></Trigger><Trigger Property='IsSelected' Value='True'><Setter TargetName='b' Property='Background' Value='#D8E3F0'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
   <Style TargetType='DatePicker'><Setter Property='FontFamily' Value='Segoe UI Variable Text,Microsoft YaHei UI'/><Setter Property='FontSize' Value='12'/><Setter Property='MinHeight' Value='32'/><Setter Property='Background' Value='{DynamicResource Field}'/><Setter Property='BorderBrush' Value='{DynamicResource Line}'/><Setter Property='Padding' Value='4,3'/></Style>
   <Style TargetType='ScrollBar'><Setter Property='Width' Value='5'/><Setter Property='Background' Value='Transparent'/></Style>
   <Style TargetType='CheckBox'><Setter Property='Foreground' Value='{DynamicResource Ink}'/><Setter Property='FontSize' Value='12'/><Setter Property='VerticalContentAlignment' Value='Center'/><Setter Property='Margin' Value='0,0,12,6'/></Style>
   </ResourceDictionary>";
   xaml=xaml.Replace("Segoe UI Variable Text,Microsoft YaHei UI","{DynamicResource UiFont}");
   xaml=xaml.Replace("<ScrollViewer x:Name='PART_ContentHost' Margin='{TemplateBinding Padding}'/>","<ScrollViewer x:Name='PART_ContentHost' Margin='{TemplateBinding Padding}' VerticalAlignment='{TemplateBinding VerticalContentAlignment}'/>");
   xaml=xaml.Replace("<Style TargetType='TextBlock'><Setter Property='Foreground' Value='{DynamicResource Ink}'/>","<Style TargetType='TextBlock'>");
   xaml=System.Text.RegularExpressions.Regex.Replace(xaml,"<Setter Property='FontSize' Value='([0-9.]+)'/>",m=>"<Setter Property='FontSize' Value='{DynamicResource "+TextAppearance.SizeKey(Double.Parse(m.Groups[1].Value,System.Globalization.CultureInfo.InvariantCulture))+"}'/>");
   xaml=System.Text.RegularExpressions.Regex.Replace(xaml,"<Style TargetType='([^']+)'>",m=>m.Value+"<Setter Property='FontWeight' Value='{DynamicResource UiWeight}'/><Setter Property='TextOptions.TextFormattingMode' Value='{DynamicResource UiFormatting}'/><Setter Property='TextOptions.TextRenderingMode' Value='{DynamicResource UiRendering}'/>");
   ResourceDictionary styles=(ResourceDictionary)XamlReader.Parse(xaml);app.Resources.MergedDictionaries.Add(styles);
   string dateStyle=@"<ResourceDictionary xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' xmlns:p='clr-namespace:System.Windows.Controls.Primitives;assembly=PresentationFramework'><Style TargetType='{x:Type DatePicker}'><Setter Property='Height' Value='36'/><Setter Property='MinHeight' Value='36'/><Setter Property='MaxHeight' Value='36'/><Setter Property='VerticalAlignment' Value='Top'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='{x:Type DatePicker}'><Border Background='{DynamicResource Field}' BorderBrush='{DynamicResource Line}' BorderThickness='1' CornerRadius='9'><Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width='22'/><ColumnDefinition Width='28'/></Grid.ColumnDefinitions><p:DatePickerTextBox x:Name='PART_TextBox' FontFamily='{DynamicResource UiFont}' FontSize='13' Height='34' MinHeight='0' Background='Transparent' Foreground='{DynamicResource Ink}' BorderThickness='0' Padding='7,0' VerticalContentAlignment='Center'/><Button x:Name='PART_ClearButton' Grid.Column='1' Padding='0' Width='22' Height='28' VerticalAlignment='Center' Focusable='False' Content='×' ToolTip='清除日期' FontSize='13' Opacity='.6'/><Button x:Name='PART_Button' Grid.Column='2' Padding='0' Height='28' VerticalAlignment='Center' Margin='0,0,2,0' Focusable='False' Content='▦' FontSize='13' Opacity='.55'/><Popup x:Name='PART_Popup' Placement='Bottom' StaysOpen='False' AllowsTransparency='True'/></Grid></Border></ControlTemplate></Setter.Value></Setter></Style></ResourceDictionary>";
   dateStyle=dateStyle.Replace("FontSize='13'","FontSize='{DynamicResource UiSize13}'").Replace("<Style TargetType='{x:Type DatePicker}'>","<Style TargetType='{x:Type DatePicker}'><Setter Property='FontWeight' Value='{DynamicResource UiWeight}'/><Setter Property='TextOptions.TextFormattingMode' Value='{DynamicResource UiFormatting}'/><Setter Property='TextOptions.TextRenderingMode' Value='{DynamicResource UiRendering}'/>");
   app.Resources.MergedDictionaries.Add((ResourceDictionary)XamlReader.Parse(dateStyle));
  }
  public static TextBlock Text(string value,double size,bool muted){TextBlock b=new TextBlock{Text=value,TextWrapping=TextWrapping.Wrap};TextAppearance.BindSize(b,size);b.SetResourceReference(TextBlock.FontWeightProperty,"UiWeight");b.SetResourceReference(TextBlock.FontFamilyProperty,"UiFont");b.SetResourceReference(TextBlock.ForegroundProperty,muted?"Muted":"Ink");return b;}
  public static Button Button(string label,Action action){Button b=new Button{Content=label};b.Click+=delegate{action();};AutomationProperties.SetName(b,label);return b;}
  public static Button Icon(string glyph,string name,Action action){Button b=Button("",action);b.Content=new TextBlock{Text=glyph,FontFamily=new FontFamily("Segoe Fluent Icons"),FontSize=13,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};b.Width=28;b.Height=28;b.Padding=new Thickness(0);b.ToolTip=name;AutomationProperties.SetName(b,name);return b;}
  public static Button Pill(string label,bool selected,Action action){Button b=Button(label,action);b.Margin=new Thickness(0,0,4,5);b.Padding=new Thickness(9,5,9,5);TextAppearance.BindSize(b,11.5);if(selected){b.SetResourceReference(System.Windows.Controls.Button.BackgroundProperty,"Selected");b.SetResourceReference(Control.FontWeightProperty,"UiEmphasisWeight");}return b;}
  public static StackPanel Field(string label,FrameworkElement input){StackPanel p=new StackPanel{Margin=new Thickness(0,0,0,13)};TextBlock t=Text(label,12,true);t.Margin=new Thickness(0,0,0,6);p.Children.Add(t);p.Children.Add(input);AutomationProperties.SetName(input,label.Replace(" · 可选",""));return p;}
  public static ComboBox Select(string[] labels,string[] values,string current,Action<string> changed){ComboBox c=new ComboBox();for(int i=0;i<labels.Length;i++){ComboBoxItem item=new ComboBoxItem{Content=labels[i],Tag=values[i]};c.Items.Add(item);if(values[i]==current)c.SelectedIndex=i;}if(c.SelectedIndex<0)c.SelectedIndex=0;if(changed!=null)c.SelectionChanged+=delegate{if(c.SelectedItem!=null)changed((string)((ComboBoxItem)c.SelectedItem).Tag);};return c;}
  public static string Value(ComboBox c){return (string)((ComboBoxItem)c.SelectedItem).Tag;}
  public static Border Divider(){return new Border{Height=1,Background=Brush("#15869BB0"),Margin=new Thickness(0,6,0,15)};}
 }
}
